/**
 * Datensicht für Partner-Mitglieder: Käufer sehen nur Leads, die an ihre Bestellungen geliefert wurden
 * (Bestellkonfiguration.buyerUserId = Nutzer); Lieferanten nur Leads ihrer Lieferantenprofile
 * (Zuordnung über die E-Mail-Adresse des Nutzers zum Lieferanten bzw. Lieferantenprofil). Interne Mitglieder sehen alles.
 */
type PartnerScope = { partnerType: "käufer" | "lieferant"; userId: number; supplierIds: number[] };
const partnerScopes = new WeakMap<object, PartnerScope>();

async function requireTenant(userId: number) {
  const context = await ensureTenantForUser(userId);
  if (!context) throw new Error("Für diesen Benutzer ist kein aktiver Mandant hinterlegt.");
  const tenant = { ...context.tenant };
  const partnerType = context.membership.partnerType;
  if (partnerType === "käufer" || partnerType === "lieferant") {
    let supplierIds: number[] = [];
    if (partnerType === "lieferant") {
      const db = await getDb();
      const user = db ? (await db.select({ email: users.email }).from(users).where(eq(users.id, userId)).limit(1))[0] : undefined;
      const email = user?.email?.trim().toLowerCase();
      if (db && email) {
        const [direct, profiles] = await Promise.all([db.select({ id: suppliers.id, name: suppliers.name, email: suppliers.email }).from(suppliers).where(eq(suppliers.tenantId, tenant.id)), db.select({ name: organizationProfiles.name, email: organizationProfiles.email }).from(organizationProfiles).where(and(eq(organizationProfiles.tenantId, tenant.id), eq(organizationProfiles.partnerType, "lieferant")))]);
        const profileNames = new Set(profiles.filter((row) => row.email?.trim().toLowerCase() === email).map((row) => row.name.toLowerCase()));
        supplierIds = direct.filter((row) => row.email?.trim().toLowerCase() === email || profileNames.has(row.name.toLowerCase())).map((row) => row.id);
      }
    }
    const db = await getDb();
    if (db) { const linked = await db.select({ id: suppliers.id }).from(suppliers).where(and(eq(suppliers.tenantId, tenant.id), eq(suppliers.userId, userId))); supplierIds = Array.from(new Set([...supplierIds, ...linked.map((row) => row.id)])); }
    partnerScopes.set(tenant, { partnerType, userId, supplierIds });
  }
  return tenant;
}

function partnerScopeOf(tenant: { id: number }) { return partnerScopes.get(tenant); }

/** Mandanten- und Partnerfilter für Lead-Abfragen – ersetzt eq(leads.tenantId, tenant.id) im Lead-Bereich. */
function leadScope(tenant: { id: number }) {
  const scope = partnerScopeOf(tenant);
  if (!scope) return and(eq(leads.tenantId, tenant.id), eq(leads.kind, "verkauf"))!; // nur Leads zum Verkauf – Vertriebskontakte (Pipeline/E-Mail-Kampagnen) bleiben außen vor
  const buyerCondition = sql`(${leads.id} IN (SELECT ld.leadId FROM leadDeliveries ld INNER JOIN orderOperationalConfigs oc ON oc.orderId = ld.orderId WHERE ld.tenantId = ${tenant.id} AND oc.buyerUserId = ${scope.userId} AND ld.result IN ('angeboten', 'angenommen', 'reklamiert')) OR ${leads.id} IN (SELECT ld2.leadId FROM leadDeliveries ld2 INNER JOIN deliveryStops ds ON ds.id = ld2.stopId WHERE ld2.tenantId = ${tenant.id} AND ds.buyerUserId = ${scope.userId} AND ld2.result IN ('angeboten', 'angenommen', 'reklamiert')))`;
  const supplierCondition = scope.supplierIds.length ? inArray(leads.supplierId, scope.supplierIds) : undefined;
  if (scope.partnerType === "käufer") return and(eq(leads.tenantId, tenant.id), eq(leads.kind, "verkauf"), supplierCondition ? or(buyerCondition, supplierCondition) : buyerCondition)!;
  return and(eq(leads.tenantId, tenant.id), eq(leads.kind, "verkauf"), supplierCondition ?? sql`1 = 0`)!;
}


