function safeCategorySpecificationName(fileName: string) {
  const stem = fileName.replace(/[^a-zA-Z0-9._-]+/g, "_").replace(/^_+|_+$/g, "").slice(0, 140);
  return stem || "kategorie-spezifikation";
}

function sanitizeCategoryBuilderDraft(value: z.infer<typeof categoryBuilderDraftSchema>) {
  const usedKeys = new Set<string>();
  const fields = value.fields.map((field, index) => {
    const baseKey = field.fieldKey.toLowerCase().replace(/[^a-z0-9_]/g, "_").replace(/^_+|_+$/g, "") || `feld_${index + 1}`;
    let fieldKey = /^[a-z]/.test(baseKey) ? baseKey : `feld_${baseKey}`;
    fieldKey = fieldKey.slice(0, 120);
    let uniqueKey = fieldKey; let suffix = 2;
    while (usedKeys.has(uniqueKey)) { uniqueKey = `${fieldKey.slice(0, 116)}_${suffix}`; suffix += 1; }
    usedKeys.add(uniqueKey);
    return { ...field, fieldKey: uniqueKey, options: field.fieldType === "auswahl" ? field.options.filter(Boolean).slice(0, 80) : field.fieldType === "ja_nein" ? ["Ja", "Nein"] : [] };
  });
  const validKeys = new Set(fields.map((field) => field.fieldKey));
  const mappings = value.mappings.filter((mapping) => validKeys.has(mapping.targetFieldKey)).map((mapping, index) => ({ ...mapping, sortOrder: index }));
  return { ...value, shortcode: value.shortcode.toUpperCase().replace(/[^A-Z0-9ÄÖÜ_-]/g, "_").slice(0, 32), fields, mappings };
}

function getDuplicateLeadIds(rows: Array<{ id: number; email: string | null; phone: string | null }>) {
  const occurrences = new Map<string, number[]>();
  for (const row of rows) for (const value of [row.email?.trim().toLowerCase(), row.phone?.replace(/\D/g, "")]) if (value && value.length > 2) occurrences.set(value, [...(occurrences.get(value) ?? []), row.id]);
  return new Set(Array.from(occurrences.values()).filter((ids) => ids.length > 1).flat());
}

