async function getOrganizationProfileDependencies(db: NonNullable<Awaited<ReturnType<typeof getDb>>>, tenantId: number, profileId: number) {
  const profile = (await db.select({ id: organizationProfiles.id, partnerType: organizationProfiles.partnerType, name: organizationProfiles.name, email: organizationProfiles.email, phone: organizationProfiles.phone, integrationId: organizationProfiles.integrationId, status: organizationProfiles.status, archivedAt: organizationProfiles.archivedAt, archivedByUserId: organizationProfiles.archivedByUserId }).from(organizationProfiles).where(and(eq(organizationProfiles.id, profileId), eq(organizationProfiles.tenantId, tenantId))).limit(1))[0];
  if (!profile) throw new Error("Dieses Käufer- oder Lieferantenprofil wurde nicht gefunden.");
  const buyerOrders = await db.select({ id: orders.id, orderNumber: orders.orderNumber, name: orders.name, buyerName: orders.buyerName, status: orders.status }).from(orders).where(and(eq(orders.tenantId, tenantId), eq(orders.buyerName, profile.name)));
  let linkedSupplier: { id: number; name: string } | undefined;
  let linkedLeads: Array<{ id: number; publicId: string; firstName: string | null; lastName: string | null; city: string | null; status: string }> = [];
  let supplierOrders: Array<{ id: number; orderNumber: string; name: string | null; buyerName: string; status: string }> = [];
  let linkedRules: Array<{ id: number; name: string; status: string }> = [];
  if (profile.partnerType === "lieferant") {
    linkedSupplier = (await db.select({ id: suppliers.id, name: suppliers.name }).from(suppliers).where(and(eq(suppliers.tenantId, tenantId), eq(suppliers.name, profile.name))).limit(1))[0];
    if (linkedSupplier) {
      linkedLeads = await db.select({ id: leads.id, publicId: leads.publicId, firstName: leads.firstName, lastName: leads.lastName, city: leads.city, status: leads.status }).from(leads).where(and(eq(leads.tenantId, tenantId), eq(leads.kind, "verkauf"), or(eq(leads.supplierId, linkedSupplier.id), eq(leads.supplierName, profile.name))));
      supplierOrders = await db.select({ id: orders.id, orderNumber: orders.orderNumber, name: orders.name, buyerName: orders.buyerName, status: orders.status }).from(orders).where(and(eq(orders.tenantId, tenantId), eq(orders.supplierId, linkedSupplier.id)));
      linkedRules = await db.select({ id: automationRules.id, name: automationRules.name, status: automationRules.status }).from(automationRules).where(and(eq(automationRules.tenantId, tenantId), eq(automationRules.supplierId, linkedSupplier.id)));
    }
  }
  const linkedOrders = Array.from(new Map([...buyerOrders, ...supplierOrders].map((order) => [order.id, order])).values());
  return { profile, linkedSupplier, linkedLeads, linkedOrders, linkedRules };
}

